import narwhals as nw
import pandas as pd
import polars as pl

@nw.narwhalify
def add_total(df):
    return df.with_columns(
        total=nw.col("price") * nw.col("quantity")
    )

# Test with pandas
df_pd = pd.DataFrame({
    "price": [10, 20, 30],
    "quantity": [2, 3, 4]
})

# Test with polars
df_pl = pl.DataFrame({
    "price": [10, 20, 30],
    "quantity": [2, 3, 4]
})

result_pd = add_total(df_pd)
result_pl = add_total(df_pl)

print("Pandas result:")
print(result_pd)
print("\nPolars result:")
print(result_pl)
